def check_m(m):
    # For a given m, we want to know if there exists a coloring 
    # of K_m using m colors such that every 3-subset of colors is a triangle.
    # This is equivalent to e_i = (m-1)/2 for all i, which implies m is odd.
    # Let's check if m=3 and m=5 work with the construction f(x,y) = x+y (mod m).

    def get_colors(m):
        # Vertices 0, ..., m-1
        # Color of edge (x,y) is (x+y) % m
        edges = []
        for x in range(m):
            for y in range(x + 1, m):
                edges.append((x, y, (x + y) % m))

        # Check if all colors are used at most (m-1)/2 times
        color_counts = {}
        for x, y, c in edges:
            color_counts[c] = color_counts.get(c, 0) + 1

        # Check if each color is used exactly (m-1)/2 times
        if any(count != (m - 1) // 2 for count in color_counts.values()):
            return False

        # Check if every triangle is rainbow
        # and every 3-subset of colors is a triangle
        triangles = []
        for x in range(m):
            for y in range(x + 1, m):
                for z in range(y + 1, m):
                    c1 = (x + y) % m
                    c2 = (y + z) % m
                    c3 = (z + x) % m
                    if c1 != c2 and c2 != c3 and c1 != c3:
                        triangles.append(tuple(sorted([c1, c2, c3])))
                    else:
                        return False # Not a proper coloring

        # Check if all triangles have different color sets
        if len(set(triangles)) != len(triangles):
            return False

        # Check if we have all possible 3-subsets of colors
        import itertools
        all_color_subsets = list(itertools.combinations(range(m), 3))
        if len(set(triangles)) != len(all_color_subsets):
            return False

        return True

    results = {}
    for m in [3, 5, 7]:
        results[m] = get_colors(m)
    print(results)

check_m(7)
